-- READ-ONLY. Literal text is the exact statement the code sends (bind parameters inlined; whitespace collapsed, SQL comments removed).
-- Placeholders: subject PSV = (SELECT id FROM subjects WHERE code = 'PSV'); change the code to try another subject (SCI, PM, MATH ...).
-- ENDPOINT: GET /api/bijak/papers
-- CODE: papers.service.ts listPapers() -> infoFor()/withPinned() -> Be09BijakQuestionSource.load() -> QuestionsRepository.unservableAmong() -> unservableReasonsOf() (questions.repository.ts ~L238).
-- Representative of ONE of the several per-request reads over EVERY question placed on every published pilihan paper (the others are Prisma findMany hydrations of live
-- versions and of pinned versions: question_versions + question_parts + part_options + answer_keys + question_version_stimuli + stimuli, which cannot be EXPLAINed from SQL text).
-- Here the pin list is all (question, pinned version) pairs of published 'simulasi' papers (the pilihan surface of the list). NOT CACHED. User-independent apart from the level filter.
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF)
SELECT q.id, coalesce(jsonb_typeof(v.import_issues) = 'array' AND v.import_issues @> '[{"code": "legacy_image_unresolved"}]'::jsonb, false) AS held, NOT ( NOT EXISTS (SELECT 1 FROM question_version_stimuli vs JOIN stimuli s ON s.id = vs.stimulus_id WHERE vs.question_version_id = v.id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT EXISTS (SELECT 1 FROM question_parts p JOIN stimuli s ON s.id = p.stimulus_id WHERE p.question_version_id = v.id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT EXISTS (SELECT 1 FROM stimulus_group_stimuli gs JOIN stimuli s ON s.id = gs.stimulus_id WHERE gs.group_id = q.group_id AND ((s.kind IN ('image', 'diagram', 'map', 'infographic', 'graph') AND s.asset_file_id IS NULL) OR (s.kind = 'table' AND s.asset_file_id IS NULL AND (s.body_ms IS NULL OR s.body_ms NOT LIKE '%|%') AND NOT coalesce((CASE jsonb_typeof(s.table_data) WHEN 'array' THEN CASE WHEN jsonb_typeof(s.table_data -> 0) = 'array' THEN jsonb_array_length(s.table_data -> 0) > 0 ELSE false END WHEN 'object' THEN CASE WHEN jsonb_typeof(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) = 'array' THEN jsonb_array_length(coalesce(s.table_data -> 'head', s.table_data -> 'headers', s.table_data -> 'columns')) > 0 AND jsonb_typeof(s.table_data -> 'rows') = 'array' ELSE false END ELSE false END), false)) OR (s.kind = 'passage' AND btrim(coalesce(s.body_ms, '')) = '' AND btrim(coalesce(s.body_en, '')) = ''))) AND NOT coalesce(jsonb_typeof(v.import_issues) = 'array' AND v.import_issues @> '[{"code": "legacy_image_unresolved"}]'::jsonb, false) ) AS media_bad, NOT (v.stimulus_flag IS NULL OR v.stimulus_flag = 'stem_duplicated' OR v.flag_dismissed_at IS NOT NULL) AS flagged, NOT NOT EXISTS (SELECT 1 FROM source_papers tsp WHERE tsp.id = v.source_paper_id AND tsp.takedown_at IS NOT NULL) AS taken_down, NOT q.is_active AS inactive, EXISTS (SELECT 1 FROM paper_placements pl JOIN paper_sections ps ON ps.id = pl.paper_section_id JOIN papers p ON p.id = ps.paper_id WHERE pl.question_id = q.id AND p.status = 'published' AND p.kind <> 'jana') AS pinned FROM (SELECT DISTINCT pl.question_id AS qid, pl.pinned_version_no AS vno FROM paper_placements pl JOIN paper_sections ps ON ps.id = pl.paper_section_id JOIN papers p ON p.id = ps.paper_id WHERE p.kind = 'pilihan' AND p.status = 'published' AND p.surface = 'simulasi') AS pin(qid, vno) JOIN questions q ON q.id = pin.qid JOIN question_versions v ON v.question_id = q.id AND v.version_no = CASE WHEN pin.vno > 0 THEN pin.vno ELSE q.live_version_no END;
